export namespace temp_pareto_core {
    export const group_resolve_with_dependencies = <Dependencies, Result>(dependencies: Dependencies, resolve: ($parent_captures: Dependencies) => Result): Result => resolve(dependencies)
}

export const Directory: d.Directory = ($, abort, $values, $lookups) => p.from.state($).decide(
    ($s): s_target.Directory => {
        switch ($s[0]) {
            case 'group': return p.option($s, ($): s_target.Directory => ['group', p.literal.group_resolve(() => {
                const $property_nodes: s_target.Directory.type_.group.nodes = p.change_context($['nodes'], ($) => p_refine.from.dictionary($).resolve(
                    ($, $id, $acyclic, $cyclic): s_target.Directory.type_.group.nodes.D => Node(
                        $,
                        abort,
                        $values,
                        $lookups,
                    ),
                ))
                return {
                    'nodes': $property_nodes,
                }
            })])
            case 'dictionary': return p.option($s, ($): s_target.Directory => ['dictionary', p.literal.group_resolve(() => {
                const $property_node: s_target.Directory.type_.dictionary.node = p.change_context($['node'], ($) => Node(
                    $,
                    abort,
                    $values,
                    $lookups,
                ))
                return {
                    'node': $property_node,
                }
            })])
            default: return p.exhaustive($s[0])
        }
    },
)

export const Node: d.Node = ($, abort, $values, $lookups) => p.from.state($).decide(
    ($s): s_target.Node => {
        switch ($s[0]) {
            case 'file': return p.option($s, ($): s_target.Node => ['file', p.literal.group_resolve(() => {
                const $property_file_extension: s_target.Node.type_.file.file_extension = p.change_context($['file extension'], ($) => $)
                const $property_type_: s_target.Node.type_.file.type_ = p.change_context($['type'], ($) => p.literal.group_resolve(() => {
                    const $property_value: s_target.Node.type_.file.type_.value = p.literal.group_resolve(() => {
                        const $property_l_id: s_target.Node.type_.file.type_.value.l_id = $
                        const $property_l_entry: s_target.Node.type_.file.type_.value.l_entry = p_lookup.acyclic.from_resolved_dictionary($values['types']).get_entry(
                            $,
                            {
                                'no_such_entry': () => abort(
                                    p.literal.group_resolve(() => {
                                        const $property_type_: s_error.Error.type_ = ['missing reference', p.literal.group_resolve(() => {
                                            const $property_identifier: s_error.Error.type_.type_.missing_reference.identifier = $
                                            return {
                                                'identifier': $property_identifier,
                                            }
                                        })]
                                        return {
                                            'type': $property_type_,
                                        }
                                    }),
                                ),
                                'no_context_lookup': () => p_unreachable(
                                    'from_resolved_dictionary supplies the lookup context directly; it cannot report an absent context',
                                ),
                                'cycle_detected': () => p_unreachable(
                                    'from_resolved_dictionary only reads already-resolved entries; it does not resolve dependencies and cannot detect a cycle',
                                ),
                            },
                        )
                        return {
                            'l id': $property_l_id,
                            'l entry': $property_l_entry,
                        }
                    })
                    const $property_constraints: s_target.Node.type_.file.type_.constraints = temp_pareto_core.group_resolve_with_dependencies(
                        {
                            'value': $property_value,
                        },
                        ($parent_captures) => {
                            const $property_public_: s_target.Node.type_.file.type_.constraints.public_ = p.from.state($parent_captures['value']['l entry']['visibility']).decide(
                                ($s): s_target.Node.type_.file.type_.constraints.public_ => {
                                    switch ($s[0]) {
                                        case 'private': return p.option($s, ($): s_target.Node.type_.file.type_.constraints.public_ => abort(
                                            p.literal.group_resolve(() => {
                                                const $property_type_: s_error.Error.type_ = ['reference constraint failed', p.literal.group_resolve(() => {
                                                    const $property_constraint: s_error.Error.type_.type_.reference_constraint_failed.constraint = 'public'
                                                    return {
                                                        'constraint': $property_constraint,
                                                    }
                                                })]
                                                return {
                                                    'type': $property_type_,
                                                }
                                            }),
                                        ))
                                        case 'private single use': return p.option($s, ($): s_target.Node.type_.file.type_.constraints.public_ => abort(
                                            p.literal.group_resolve(() => {
                                                const $property_type_: s_error.Error.type_ = ['reference constraint failed', p.literal.group_resolve(() => {
                                                    const $property_constraint: s_error.Error.type_.type_.reference_constraint_failed.constraint = 'public'
                                                    return {
                                                        'constraint': $property_constraint,
                                                    }
                                                })]
                                                return {
                                                    'type': $property_type_,
                                                }
                                            }),
                                        ))
                                        case 'public': return p.option($s, ($): s_target.Node.type_.file.type_.constraints.public_ => $)
                                        default: return p.exhaustive($s[0])
                                    }
                                },
                            )
                            return {
                                'public': $property_public_,
                            }
                        },
                    )
                    return {
                        'value': $property_value,
                        'constraints': $property_constraints,
                    }
                }))
                return {
                    'file extension': $property_file_extension,
                    'type': $property_type_,
                }
            })])
            case 'directory': return p.option($s, ($): s_target.Node => ['directory', Directory(
                $,
                abort,
                $values,
                $lookups,
            )])
            default: return p.exhaustive($s[0])
        }
    },
)

export const Type_Specification: d.Type_Specification = ($, abort) => p.literal.group_resolve(() => {
    const $property_schema: s_target.Type_Specification.schema = p.change_context($['schema'], ($) => p.literal.group_resolve(() => {
        const $property_structure: s_target.Type_Specification.schema.structure = p.change_context($['structure'], ($) => structure.Structure(
            $,
            abort,
            null,
            {
                'sibling namespaces': p_lookup.acyclic.not_set(),
            },
        ))
        const $property_resolver: s_target.Type_Specification.schema.resolver = p.change_context($['resolver'], ($) => temp_pareto_core.group_resolve_with_dependencies(
            {
                'structure': $property_structure,
            },
            ($parent_captures) => {
                const $property_declarations: s_target.Type_Specification.schema.resolver.declarations = p.change_context($['declarations'], ($) => declarations.Declaration_Namespace(
                    $,
                    abort,
                    {
                        'definition': $parent_captures['structure'],
                    },
                    {
                        'sibling namespaces': p_lookup.acyclic.not_set(),
                    },
                ))
                const $property_implementations: s_target.Type_Specification.schema.resolver.implementations = p.change_context($['implementations'], ($) => resolver.Resolver(
                    $,
                    abort,
                    {
                        'definition': $parent_captures['structure'],
                        'declarations': $property_declarations,
                        'sibling declarations': p.literal.not_set(),
                        'sibling namespaces': p.literal.not_set(),
                    },
                    null,
                ))
                return {
                    'declarations': $property_declarations,
                    'implementations': $property_implementations,
                }
            },
        ))
        return {
            'structure': $property_structure,
            'resolver': $property_resolver,
        }
    }))
    const $property_directory: s_target.Type_Specification.directory = p.change_context($['directory'], ($) => Directory(
        $,
        abort,
        {
            'types': $property_schema['structure']['types'],
        },
        null,
    ))
    return {
        'schema': $property_schema,
        'directory': $property_directory,
    }
})

